test('pending worksite draws scaffold and blocks finished interaction, then reveals final art at wallclock boundary',()=>{
 const originalNow=Date.now;let clock=Date.UTC(2026,9,26,4);Date.now=()=>clock;
 try{harness(({scene,events,frames,contacts,point,drawn,press})=>{
  const w={...world,lastSeenAt:clock,exhibits:[{...world.exhibits[0],startedAt:clock,readyAt:clock+15000}]};scene.setWorld(w,{});frames.shift()(100);assert.ok(drawn.includes('construction_site'));assert.equal(drawn.includes('house'),false);const p=point(.5,.5),event={pointerId:1,clientX:p.x,clientY:p.y-50,pointerType:'touch'};events.pointerdown(event);events.pointercancel(event);assert.equal(contacts.length,0);
  clock+=15000;drawn.length=0;frames.shift()(160);assert.ok(drawn.includes('house'));press(event);assert.equal(contacts[0]?.entity,'exhibit');
 });}finally{Date.now=originalNow;}
});
