  const tiles=[[0,0],[1,0],[0,1],[1,1],[2,0],[2,1],[0,2]].map(([x,y])=>({id:`${x}:${y}`,x,y,kind:'land'}));assets.sprite=k=>art.sprites[k];assets.spriteAlphaAt=(key,u,v)=>(scenario==='unknown-house'&&key==='camping_dog_workshop')||(scenario==='unknown-plant'&&key==='drum_pumpkin')?null:read(key,u,v);scene.setWorld({id:'my-inspiration-garden',tiles,edges:[],plants:[{id:'pumpkin',varietyId:'drum',tileId:'0:1',readyAt:0,plantedAt:0}],exhibits:[{id:'dog',artKey:'camping_dog_workshop',sampleId:'camping_dog_workshop',blueprintId:'own-dog',tileId:'1:0',x:1,y:0,interaction:'camp'}],avatarTileId:spawn},{drum:{id:'drum',artKey:'drum_pumpkin',interaction:'drum'}});if(['edit','land','platform','plant'].includes(scenario))scene.setMode({kind:scenario});frame(100);const sp=art.sprites.drum_pumpkin,z=scene.getCamera().zoom,p=point(0,1),w=sp.width*z,h=w*sp.frame.h/sp.frame.w,u=scenario==='opaque'?.8:.6,v=.5,angle=Math.sin(100/2100+1)*.018,dx=(u-sp.anchor[0])*w,dy=(v-sp.anchor[1])*h,x=p.x+Math.cos(angle)*dx-Math.sin(angle)*dy,y=p.y+8*z+Math.sin(angle)*dx+Math.cos(angle)*dy,e={pointerId:1,clientX:x,clientY:y,pointerType:'touch'};assert.ok(read('drum_pumpkin',u,v)>=32);events.pointerdown(e);events.pointerup(e);const hit=taps.at(-1)??approaches.at(-1)??(contacts.at(-1)?{kind:contacts.at(-1).entity,id:contacts.at(-1).plantId}:null);if(scenario==='clear')assert.equal(hit?.id,'pumpkin');else assert.notEqual(hit?.id,'pumpkin',scenario);
