test('growing countdown owns only its bubble; seedling art remains an ordinary immediate selection',()=>harness(({scene,events,frame,point,taps})=>{
 const growing={id:'my-inspiration-garden',tiles,edges:[],plants:[{id:'growing',tileId:'0:0',varietyId:'radish',plantedAt:Date.now(),readyAt:Date.now()+45000}],exhibits:[],avatarTileId:'3:2'};
 scene.setWorld(growing,{radish:{id:'radish',artKey:'radish',interaction:'sway'}});frame(100);const p=point(0,0),z=scene.getCamera().zoom,e={pointerType:'mouse',pointerId:1,button:0,clientX:p.x,clientY:p.y-30*z};
 events.pointerdown(e);events.pointerup({...e});assert.equal(taps.length,0,'first countdown tap must not open context or move the camera before the second tap');
 scene.cancelInteractions();const art={...e,pointerId:2,clientY:p.y};events.pointerdown(art);events.pointerup({...art});assert.equal(taps.length,1);assert.equal(taps[0].kind,'plant');assert.equal(taps[0].id,'growing');
}));

for(const type of ['mouse','touch'])test(`real Canvas ${type} countdown pair emits one exact plant intent without selection or camera jump`,()=>harness(({scene,events,frame,point,taps,growthSkips})=>{
 const plant={id:'growing',tileId:'0:0',varietyId:'radish',plantedAt:Date.now(),readyAt:Date.now()+45000};scene.setWorld({id:'my-inspiration-garden',tiles,edges:[],plants:[plant],exhibits:[],avatarTileId:'3:2'},{radish:{id:'radish',artKey:'radish',interaction:'sway'}});frame(100);const camera=scene.getCamera(),p=point(0,0),e={pointerType:type,pointerId:1,button:0,clientX:p.x,clientY:p.y-30*camera.zoom};events.pointerdown(e);events.pointerup({...e});assert.deepEqual(scene.getCamera(),camera);events.pointerdown({...e,pointerId:2});events.pointerup({...e,pointerId:2});assert.equal(growthSkips.length,1);assert.deepEqual(growthSkips[0],plant);assert.equal(taps.length,0);
}));
for(const interrupt of ['drag','pinch','cancel','visit','close','remove'])test(`real Canvas ${interrupt} interrupts a countdown double tap`,()=>harness(({scene,events,frame,point,growthSkips})=>{
 const plant={id:'growing',tileId:'0:0',varietyId:'radish',plantedAt:Date.now(),readyAt:Date.now()+45000},w={id:'my-inspiration-garden',tiles,edges:[],plants:[plant],exhibits:[],avatarTileId:'3:2'},v={radish:{id:'radish',artKey:'radish',interaction:'sway'}};scene.setWorld(w,v);frame(100);const p=point(0,0),e={pointerType:'touch',pointerId:1,button:0,clientX:p.x,clientY:p.y-30*scene.getCamera().zoom};events.pointerdown(e);events.pointerup({...e});
 if(interrupt==='drag'){events.pointerdown({...e});events.pointermove({...e,clientX:e.clientX+25});events.pointerup({...e,clientX:e.clientX+25});}
 if(interrupt==='pinch'){events.pointerdown({...e});events.pointerdown({...e,pointerId:2,isPrimary:false});events.pointerup({...e,pointerId:2,isPrimary:false});events.pointerup({...e});}
 if(interrupt==='cancel')events.pointercancel({...e});if(interrupt==='close')scene.cancelUncommittedTouch();if(interrupt==='visit')scene.setWorld({...w,id:'friend'},v);if(interrupt==='remove')scene.setWorld({...w,plants:[]},v);events.pointerdown({...e});events.pointerup({...e});assert.equal(growthSkips.length,0);
}));

test('a countdown single tap still selects its unchanged plant if natural maturity arrives during the double-tap window',()=>{
 const oldTimeout=globalThis.setTimeout,oldClear=globalThis.clearTimeout,oldNow=Date.now,timers=new Map();let id=0,wall=1793062800000;globalThis.setTimeout=fn=>(timers.set(++id,fn),id);globalThis.clearTimeout=id=>timers.delete(id);Date.now=()=>wall;
 try{harness(({scene,events,frame,point,taps,growthSkips})=>{const plant={id:'almost-ready',tileId:'0:0',varietyId:'radish',plantedAt:wall-14900,readyAt:wall+100};scene.setWorld({id:'my-inspiration-garden',tiles,edges:[],plants:[plant],exhibits:[],avatarTileId:'3:2'},{radish:{id:'radish',artKey:'radish',interaction:'sway'}});frame(100);const p=point(0,0),e={pointerType:'touch',pointerId:1,button:0,clientX:p.x,clientY:p.y-30*scene.getCamera().zoom};events.pointerdown(e);events.pointerup({...e});wall+=400;for(const fn of [...timers.values()])fn();assert.equal(taps.length,1);assert.equal(taps[0].id,'almost-ready');assert.equal(growthSkips.length,0);});}finally{globalThis.setTimeout=oldTimeout;globalThis.clearTimeout=oldClear;Date.now=oldNow;}
});
